+fn replace(payload: &Path, destination: &Path, backup: &Path) -> Result<()> {
+    let existed = file::exists(destination);
+    if existed {
+        file::rename(destination, backup)?;
+    }
+    if let Err(error) = file::rename(payload, destination) {
+        if existed {
+            file::rename(backup, destination).wrap_err("restoring previous plugin")?;
+        }
+        return Err(error);
+    }
+    Ok(())
+}
+
+pub(crate) fn validate_artifact(artifact: &packslip::model::Artifact) -> Result<()> {
+    ensure!(
+        artifact.extensions.get("mise").and_then(|v| v.get("plugin")).and_then(|v| v.as_str()) == Some("vfox"),
