+/// targets might otherwise be resolved while unpacking a later archive entry.
+pub(crate) fn validate_archive(path: &Path) -> Result<()> {
+    let reader = flate2::read::GzDecoder::new(std::fs::File::open(path)?);
+    let mut archive = jdx_tar::Archive::new(reader);
+    for entry in archive.entries()? {
+        let entry = entry?;
+        ensure!(matches!(entry.entry_type(), jdx_tar::EntryType::File | jdx_tar::EntryType::Directory), "vfox plugin archive contains a link or special file");
+        let path = entry.path()?;
+        for component in path.components() {
+            let Component::Normal(name) = component else {
+                bail!("vfox plugin archive contains an unsafe path");
+            };
+            let name = name.to_string_lossy();
+            ensure!(!name.contains(['\\', ':']) && !name.eq_ignore_ascii_case(".git") && !name.eq_ignore_ascii_case(STATE_FILE), "vfox plugin archive contains a reserved or unsafe path");
+        }
+    }
+    Ok(())
+}
+
+pub(crate) fn validate_layout(path: &Path) -> Result<()> {
+    ensure!(path.join("metadata.lua").is_file(), "vfox plugin archive must contain metadata.lua at its root");
+    Ok(())
+}
